/**
 * Large-company setup: "when this kind of work is sold, what must happen". Rules trigger on structured values (a
 * service, a category, a flag such as utility_requirement = LINE_DROP, or an answer), never on quote titles. The
 * human-readable titles are written afterwards. Pure.
 */
import type { Answers, Category, PlaybookRule, RateCardDefinition, SchedulingClass, TaskKind } from './rules.ts';
import { matches } from './answers.ts';

export interface PlaybookItem { id: string; serviceKey: string; serviceName: string; category: Category; answers: Answers; flags: Record<string, string> }
export type TaskDue = 'immediate' | 'before_job' | { daysAfterApproval?: number };
export interface TaskSpec { key: string; kind: TaskKind; title: string; due: TaskDue; ruleKey: string; itemIds: string[] }
export interface PlaybookResult {
  tasks: TaskSpec[];
  schedulingClass: SchedulingClass;
  requiredAnswers: { question: string; label: string; itemIds: string[] }[];
  resources: { resource: string; mode: 'reserve' | 'rent' | 'vendor'; itemIds: string[] }[];
  accounting: { label: string; commissionDeduction?: number; itemIds: string[] }[];
}

const URGENCY: Record<SchedulingClass, number> = { normal: 0, priority: 1, asap: 2 };

export function taskTitle(kind: TaskKind, ctx: { services?: string[]; resource?: string } = {}): string {
  const what = ctx.services && ctx.services.length ? ` (${ctx.services.join(', ')})` : '';
  const res = ctx.resource ? ctx.resource.replace(/_/g, ' ') : '';
  switch (kind) {
    case 'utility_contact': return `Contact the utility now and update the ticket${what}`;
    case 'utility_disconnect': return `Arrange the line drop with the utility before the job${what}`;
    case 'locate_request': return `Submit the OKIE locate request${what}`;
    case 'material_check': return `Check or order the special materials${what}`;
    case 'rental': return `Reserve or rent the ${res || 'equipment'}${what}`;
    case 'vendor': return `Book the ${res || 'outside vendor'}${what}`;
    case 'gate_code': return `Get the gate code and access details${what}`;
    case 'accounting': return `Record the internal adjustment${what}`;
    default: return `Follow up${what}`;
  }
}

function triggers(rule: PlaybookRule, item: PlaybookItem): boolean {
  const w = rule.when;
  if (w.service && w.service !== item.serviceKey) return false;
  if (w.category && w.category !== item.category) return false;
  if (w.flag && item.flags[w.flag.name] !== w.flag.value) return false;
  if (w.question && !matches(w.question, item.answers)) return false;
  return !!(w.service || w.category || w.flag || w.question);
}

export function evaluatePlaybooks(def: RateCardDefinition, items: PlaybookItem[]): PlaybookResult {
  const res: PlaybookResult = { tasks: [], schedulingClass: 'normal', requiredAnswers: [], resources: [], accounting: [] };
  for (const rule of def.playbooks) {
    const hit = items.filter((i) => triggers(rule, i));
    if (!hit.length) continue;
    const ids = hit.map((i) => i.id);
    const names = [...new Set(hit.map((i) => i.serviceName))];
    const resource = rule.actions.find((a) => a.kind === 'resource');
    rule.actions.forEach((a, n) => {
      if (a.kind === 'task') {
        res.tasks.push({
          key: `${rule.key}:${n}`, kind: a.task, due: a.due, ruleKey: rule.key, itemIds: ids,
          title: a.title?.trim() || taskTitle(a.task, { services: names, resource: resource && resource.kind === 'resource' ? resource.resource : undefined }),
        });
      } else if (a.kind === 'scheduling') {
        if (URGENCY[a.class] > URGENCY[res.schedulingClass]) res.schedulingClass = a.class;
      } else if (a.kind === 'require_answer') {
        if (!res.requiredAnswers.some((r) => r.question === a.question)) res.requiredAnswers.push({ question: a.question, label: a.label ?? a.question.replace(/_/g, ' '), itemIds: ids });
      } else if (a.kind === 'resource') {
        res.resources.push({ resource: a.resource, mode: a.mode, itemIds: ids });
      } else if (a.kind === 'accounting') {
        res.accounting.push({ label: a.label, commissionDeduction: a.commissionDeduction, itemIds: ids });
      }
    });
  }
  return res;
}

/** A proposal title from what was sold: "Tree removal and stump grinding", "Tree removal, cabling and 2 more". */
export function proposalTitle(names: string[]): string {
  const uniq = [...new Set(names.filter(Boolean))];
  if (uniq.length === 0) return 'Tree care proposal';
  // Lower-case the first letter of later names, unless the name is a proper name ("Tree Health Membership").
  const lower = uniq.map((n, i) => (i === 0 || /[A-Z]/.test(n.slice(1)) ? n : n.charAt(0).toLowerCase() + n.slice(1)));
  if (lower.length === 1) return lower[0];
  if (lower.length === 2) return `${lower[0]} and ${lower[1]}`;
  if (lower.length === 3) return `${lower[0]}, ${lower[1]} and ${lower[2]}`;
  return `${lower[0]}, ${lower[1]} and ${lower.length - 2} more`;
}
